BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(23);
INSERT INTO auth.users (id,email) VALUES ('49910000-0000-4000-8000-000000000001','properties-owner@example.test'),('49910000-0000-4000-8000-000000000002','properties-outsider@example.test');
INSERT INTO public.projects (id,owner_id,name,key) VALUES ('49910000-0000-4000-8000-000000000003','49910000-0000-4000-8000-000000000001','Extended properties','EPT');
INSERT INTO public.pages (id,project_id,position,database_schema) VALUES ('49910000-0000-4000-8000-000000000004','49910000-0000-4000-8000-000000000003','a','[{"id":"49910000-0000-4000-8000-000000000010","name":"Amount","type":"number"},{"id":"49910000-0000-4000-8000-000000000011","name":"Status","type":"select","options":[{"id":"49910000-0000-4000-8000-000000000020","name":"Ready","color":"#22c55e"},{"id":"49910000-0000-4000-8000-000000000021","name":"Later","color":"#3b82f6"}]},{"id":"49910000-0000-4000-8000-000000000012","name":"Tags","type":"multi_select","options":[{"id":"49910000-0000-4000-8000-000000000020","name":"Ready","color":"#22c55e"},{"id":"49910000-0000-4000-8000-000000000021","name":"Later","color":"#3b82f6"}]},{"id":"49910000-0000-4000-8000-000000000013","name":"Created","type":"created_at"}]');
INSERT INTO public.pages (id,project_id,parent_id,position) VALUES ('49910000-0000-4000-8000-000000000005','49910000-0000-4000-8000-000000000003','49910000-0000-4000-8000-000000000004','a'),('49910000-0000-4000-8000-000000000006','49910000-0000-4000-8000-000000000003','49910000-0000-4000-8000-000000000004','b');
CREATE FUNCTION pg_temp.edit_property(input jsonb, target uuid DEFAULT '49910000-0000-4000-8000-000000000005', actor uuid DEFAULT '49910000-0000-4000-8000-000000000001') RETURNS text LANGUAGE sql AS $$
 SELECT public.update_page_database_guarded('49910000-0000-4000-8000-000000000003',target,actor,input)->>'status';
$$;
SELECT is(pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000010","value":-12.5,"expected":null}','49910000-0000-4000-8000-000000000005'),'updated','signed decimal persists');
SELECT throws_ok($$ SELECT pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000010","value":"12a","expected":-12.5}') $$,'22023','Invalid number','letters cannot enter numeric storage');
SELECT is(pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000010","value":0,"expected":-12.5,"kind":"agent"}','49910000-0000-4000-8000-000000000005'),'updated','Numo uses the same numeric write');
SELECT is((SELECT updated_kind FROM public.pages WHERE id='49910000-0000-4000-8000-000000000005'),'agent','Numo edits retain agent attribution');
SELECT is(pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000010","value":1,"expected":-12.5}','49910000-0000-4000-8000-000000000005'),'conflict','stale numeric edits are refused');
SELECT is(pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000011","value":"49910000-0000-4000-8000-000000000020","expected":null}','49910000-0000-4000-8000-000000000005'),'updated','single option persists');
SELECT throws_ok($$ SELECT pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000011","value":["49910000-0000-4000-8000-000000000020","49910000-0000-4000-8000-000000000021"],"expected":"49910000-0000-4000-8000-000000000020"}') $$,'22023','Invalid selection','single select rejects multiple options');
SELECT throws_ok($$ SELECT pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000011","value":"49910000-0000-4000-8000-000000000025","expected":"49910000-0000-4000-8000-000000000020"}') $$,'22023','Invalid selection','unknown option is rejected');
SELECT is(pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000012","value":["49910000-0000-4000-8000-000000000020","49910000-0000-4000-8000-000000000021"],"expected":null}','49910000-0000-4000-8000-000000000005'),'updated','multiple options persist');
SELECT throws_ok($$ SELECT pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000012","value":["49910000-0000-4000-8000-000000000020","49910000-0000-4000-8000-000000000020"],"expected":["49910000-0000-4000-8000-000000000020","49910000-0000-4000-8000-000000000021"]}') $$,'22023','Invalid selections','duplicate options are rejected');
SELECT throws_ok($$ SELECT pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000012","value":["49910000-0000-4000-8000-000000000025"],"expected":["49910000-0000-4000-8000-000000000020","49910000-0000-4000-8000-000000000021"]}') $$,'22023','Invalid selections','unknown multi-select option is rejected');
SELECT is(pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000013","value":null,"expected":null}','49910000-0000-4000-8000-000000000005'),'conflict','creation property cannot be cleared');
SELECT throws_ok($$ UPDATE public.pages SET property_values=property_values || '{"49910000-0000-4000-8000-000000000013":"fake"}' WHERE id='49910000-0000-4000-8000-000000000005' $$,'22023','Creation time is read-only','direct storage cannot spoof creation metadata');
SELECT is(pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000010","value":2,"expected":0}','49910000-0000-4000-8000-000000000005','49910000-0000-4000-8000-000000000002'),'not_found','nonmembers cannot edit new types');
SELECT throws_ok($$ UPDATE public.pages SET database_schema='[{"id":"49910000-0000-4000-8000-000000000010","name":"Amount","type":"number"},{"id":"49910000-0000-4000-8000-000000000011","name":"Status","type":"select","options":[{"id":"49910000-0000-4000-8000-000000000020","name":"Ready","color":"red"},{"id":"49910000-0000-4000-8000-000000000021","name":"Later","color":"#3b82f6"}]},{"id":"49910000-0000-4000-8000-000000000012","name":"Tags","type":"multi_select","options":[{"id":"49910000-0000-4000-8000-000000000020","name":"Ready","color":"#22c55e"},{"id":"49910000-0000-4000-8000-000000000021","name":"Later","color":"#3b82f6"}]},{"id":"49910000-0000-4000-8000-000000000013","name":"Created","type":"created_at"}]' WHERE id='49910000-0000-4000-8000-000000000004' $$,'22023','Invalid option','invalid option color is rejected');
SELECT throws_ok($$ UPDATE public.pages SET database_schema='[{"id":"49910000-0000-4000-8000-000000000010","name":"Amount","type":"number"},{"id":"49910000-0000-4000-8000-000000000011","name":"Status","type":"select","options":[{"id":"49910000-0000-4000-8000-000000000020","name":"Ready","color":"#22c55e"},{"id":"49910000-0000-4000-8000-000000000021","name":" READY ","color":"#3b82f6"}]},{"id":"49910000-0000-4000-8000-000000000012","name":"Tags","type":"multi_select","options":[{"id":"49910000-0000-4000-8000-000000000020","name":"Ready","color":"#22c55e"},{"id":"49910000-0000-4000-8000-000000000021","name":"Later","color":"#3b82f6"}]},{"id":"49910000-0000-4000-8000-000000000013","name":"Created","type":"created_at"}]' WHERE id='49910000-0000-4000-8000-000000000004' $$,'22023','Invalid option','duplicate option names are rejected');
SELECT is(pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000011","value":"49910000-0000-4000-8000-000000000020","expected":null}','49910000-0000-4000-8000-000000000006'),'updated','trash fixture receives single option');
SELECT is(pg_temp.edit_property('{"operation":"value","propertyId":"49910000-0000-4000-8000-000000000012","value":["49910000-0000-4000-8000-000000000020","49910000-0000-4000-8000-000000000021"],"expected":null}','49910000-0000-4000-8000-000000000006'),'updated','trash fixture receives multiple options');
UPDATE public.pages SET deleted_at=now() WHERE id='49910000-0000-4000-8000-000000000006';
SELECT is(pg_temp.edit_property('{"operation":"schema","schema":[{"id":"49910000-0000-4000-8000-000000000010","name":"Amount","type":"number"},{"id":"49910000-0000-4000-8000-000000000011","name":"Status","type":"select","options":[{"id":"49910000-0000-4000-8000-000000000021","name":"Later","color":"#3b82f6"}]},{"id":"49910000-0000-4000-8000-000000000012","name":"Tags","type":"multi_select","options":[{"id":"49910000-0000-4000-8000-000000000021","name":"Later","color":"#3b82f6"}]},{"id":"49910000-0000-4000-8000-000000000013","name":"Created","type":"created_at"}],"revision":0}','49910000-0000-4000-8000-000000000004'),'updated','option deletion updates schema atomically');
SELECT ok((SELECT NOT property_values ? '49910000-0000-4000-8000-000000000011' FROM public.pages WHERE id='49910000-0000-4000-8000-000000000005'),'deleted single option is removed from live entry');
SELECT is((SELECT property_values->'49910000-0000-4000-8000-000000000012' FROM public.pages WHERE id='49910000-0000-4000-8000-000000000005'),'["49910000-0000-4000-8000-000000000021"]'::jsonb,'other selected options are preserved');
SELECT ok((SELECT NOT property_values ? '49910000-0000-4000-8000-000000000011' AND property_values->'49910000-0000-4000-8000-000000000012'='["49910000-0000-4000-8000-000000000021"]'::jsonb FROM public.pages WHERE id='49910000-0000-4000-8000-000000000006'),'deleted options are cleared from trash too');
SELECT is(pg_temp.edit_property('{"operation":"schema","schema":[{"id":"49910000-0000-4000-8000-000000000010","name":"Amount","type":"number"},{"id":"49910000-0000-4000-8000-000000000011","name":"Status","type":"select","options":[{"id":"49910000-0000-4000-8000-000000000020","name":"Ready","color":"#22c55e"},{"id":"49910000-0000-4000-8000-000000000021","name":"Later","color":"#3b82f6"}]},{"id":"49910000-0000-4000-8000-000000000012","name":"Tags","type":"multi_select","options":[{"id":"49910000-0000-4000-8000-000000000020","name":"Ready","color":"#22c55e"},{"id":"49910000-0000-4000-8000-000000000021","name":"Later","color":"#3b82f6"}]},{"id":"49910000-0000-4000-8000-000000000013","name":"Created","type":"created_at"}],"revision":0}','49910000-0000-4000-8000-000000000004'),'conflict','stale option edits are refused');
SELECT * FROM finish();
ROLLBACK;
